/// <reference lib="webworker" />
import { CacheableResponsePlugin } from "workbox-cacheable-response";
import { clientsClaim } from "workbox-core";
import { ExpirationPlugin } from "workbox-expiration";
import { registerRoute } from "workbox-routing";
import { CacheFirst, NetworkOnly, StaleWhileRevalidate } from "workbox-strategies";

declare let self: ServiceWorkerGlobalScope;
self.skipWaiting();
clientsClaim();

// Authority-dependent bytes must be rechecked against the server on every read.
// Purge exact legacy attachment caches that could contain authority-sensitive URLs.
// Never delete IndexedDB, local library data, or immutable assets.
self.addEventListener("activate", event => {
	event.waitUntil(Promise.all([caches.delete("covers"), caches.delete("favicons")]));
});
registerRoute(
	({ url }) => url.origin === self.location.origin && (
		["/covers/", "/data/", "/uploads/", "/originals/", "/api/", "/auth/"].some(prefix => url.pathname.startsWith(prefix)) ||
		["/proxy", "/og-image"].some(prefix => url.pathname === prefix || url.pathname.startsWith(prefix + "/"))
	),
	new NetworkOnly({ fetchOptions: { cache: "no-store" } }),
	"GET"
);


registerRoute(
	({ request, url }) =>
		url.pathname.startsWith("/assets/") ||
		url.pathname.startsWith("/_app/") ||
		(request.url.startsWith("/fonts/") && request.destination === "font") ||
		(request.url.startsWith("/images/") && request.destination === "image"),
	new CacheFirst({
		cacheName: "assets",
		plugins: [new CacheableResponsePlugin({ statuses: [200] })]
	})
);

registerRoute(
	({ request }) => request.url.includes("/favicons") || request.url.includes("faviconV2"),
	new StaleWhileRevalidate({
		cacheName: "favicons",
		plugins: [
			new CacheableResponsePlugin({ statuses: [200] }),
			new ExpirationPlugin({
				maxEntries: 1000,
				maxAgeSeconds: 3600 * 24 * 30
			})
		]
	}),
	"GET"
);

